use std::{fs, path::{Path, PathBuf}};
use rusqlite::{params, Connection};
use serde::Serialize;
use crate::library::LibraryRecord;

pub type CatalogResult<T> = Result<T, String>;
#[derive(Clone, Debug, Serialize)] #[serde(rename_all="camelCase")]
pub struct UserProfile { pub id: i64, pub name: String, pub avatar: Option<String> }
#[derive(Clone, Debug, Serialize)] #[serde(rename_all="camelCase")]
pub struct Installation { pub id: i64, pub source: String, pub platform: String, pub install_path: String, pub install_kind: String, pub available: bool, pub requires_disc: bool }
#[derive(Clone, Debug, Serialize)] #[serde(rename_all="camelCase")]
pub struct CatalogGame { pub id: i64, pub identity_key: String, pub title: String, pub platform: String, pub favorite: bool, pub installations: Vec<Installation> }
#[derive(Clone, Debug)]
pub struct InstallationInput { pub identity_key:String, pub title:String, pub platform:String, pub source:String, pub path:String, pub requires_disc:bool }
impl InstallationInput { pub fn new(identity_key: impl Into<String>, title: impl Into<String>, platform: impl Into<String>, source: impl Into<String>, path: impl Into<String>, requires_disc: bool) -> Self { Self { identity_key:identity_key.into(), title:title.into(), platform:platform.into(), source:source.into(), path:path.into(), requires_disc } } }
pub struct Catalog { db: PathBuf, root: PathBuf }
impl Catalog {
 pub fn open(root: &Path) -> CatalogResult<Self> { fs::create_dir_all(root).map_err(|e|e.to_string())?; let instance=Self{db:root.join("baconconsole.sqlite3"),root:root.to_path_buf()}; let mut conn=instance.connection()?; instance.migrate(&mut conn)?; instance.import_legacy(&mut conn)?; Ok(instance) }
 fn connection(&self)->CatalogResult<Connection>{ Connection::open(&self.db).map_err(|e|e.to_string()) }
 fn migrate(&self, conn:&mut Connection)->CatalogResult<()> { conn.execute_batch("BEGIN; CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY); CREATE TABLE IF NOT EXISTS games(id INTEGER PRIMARY KEY, identity_key TEXT NOT NULL UNIQUE, title TEXT NOT NULL, platform TEXT NOT NULL); CREATE TABLE IF NOT EXISTS installations(id INTEGER PRIMARY KEY, game_id INTEGER NOT NULL, source TEXT NOT NULL, platform TEXT NOT NULL, install_path TEXT NOT NULL, install_kind TEXT NOT NULL, available INTEGER NOT NULL, requires_disc INTEGER NOT NULL, UNIQUE(game_id, source, install_path)); CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, avatar TEXT); CREATE TABLE IF NOT EXISTS user_preferences(user_id INTEGER NOT NULL, key TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY(user_id,key)); CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER NOT NULL, game_id INTEGER NOT NULL, PRIMARY KEY(user_id,game_id)); CREATE TABLE IF NOT EXISTS play_history(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL,game_id INTEGER NOT NULL,started_at INTEGER NOT NULL,ended_at INTEGER); INSERT OR IGNORE INTO users(id,name) VALUES(1,'Convidado'); INSERT OR IGNORE INTO user_preferences(user_id,key,value) VALUES(1,'active_user','1'); INSERT OR IGNORE INTO schema_migrations(version) VALUES(1); COMMIT;").map_err(|e|e.to_string()) }
 fn import_legacy(&self, conn:&mut Connection)->CatalogResult<()> { let imported:bool=conn.query_row("SELECT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2)",[],|r|r.get(0)).map_err(|e|e.to_string())?; if imported{return Ok(())}; let path=self.root.join("library.json"); if path.exists(){ let records:Vec<LibraryRecord>=serde_json::from_str(&fs::read_to_string(path).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?; for record in records { self.upsert_with(conn, InstallationInput::new(format!("bacondisc:{}",record.id),record.title,"windows",record.install_kind,record.install_path,record.requires_disc))?; }} conn.execute("INSERT INTO schema_migrations(version) VALUES(2)",[]).map_err(|e|e.to_string())?; Ok(()) }
 fn upsert_with(&self,conn:&Connection,input:InstallationInput)->CatalogResult<()> { conn.execute("INSERT INTO games(identity_key,title,platform) VALUES(?1,?2,?3) ON CONFLICT(identity_key) DO UPDATE SET title=excluded.title,platform=excluded.platform",params![input.identity_key,input.title,input.platform]).map_err(|e|e.to_string())?; let id:i64=conn.query_row("SELECT id FROM games WHERE identity_key=?1",params![input.identity_key],|r|r.get(0)).map_err(|e|e.to_string())?; conn.execute("INSERT INTO installations(game_id,source,platform,install_path,install_kind,available,requires_disc) VALUES(?1,?2,?3,?4,?5,1,?6) ON CONFLICT(game_id,source,install_path) DO UPDATE SET available=1,requires_disc=excluded.requires_disc",params![id,input.source,input.platform,input.path,input.source,input.requires_disc as i32]).map_err(|e|e.to_string())?; Ok(()) }
 pub fn upsert_installation(&self,input:InstallationInput)->CatalogResult<()> { let conn=self.connection()?; self.upsert_with(&conn,input) }
 pub fn active_user(&self)->CatalogResult<UserProfile>{ let conn=self.connection()?; conn.query_row("SELECT u.id,u.name,u.avatar FROM users u JOIN user_preferences p ON p.user_id=u.id WHERE p.key='active_user' AND p.value=CAST(u.id AS TEXT) LIMIT 1",[],|r|Ok(UserProfile{id:r.get(0)?,name:r.get(1)?,avatar:r.get(2)?})).map_err(|e|e.to_string()) }
 pub fn list_users(&self)->CatalogResult<Vec<UserProfile>> { let conn=self.connection()?; let mut statement=conn.prepare("SELECT id,name,avatar FROM users ORDER BY id").map_err(|e|e.to_string())?; let rows=statement.query_map([],|r|Ok(UserProfile{id:r.get(0)?,name:r.get(1)?,avatar:r.get(2)?})).map_err(|e|e.to_string())?; let users=rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?; Ok(users) }
 pub fn create_user(&self,name:&str,avatar:Option<&str>)->CatalogResult<UserProfile>{ let conn=self.connection()?; conn.execute("INSERT INTO users(name,avatar) VALUES(?1,?2)",params![name,avatar]).map_err(|e|e.to_string())?; Ok(UserProfile{id:conn.last_insert_rowid(),name:name.into(),avatar:avatar.map(str::to_owned)}) }
 pub fn set_active_user(&self,user_id:i64)->CatalogResult<()> { let conn=self.connection()?; let exists:bool=conn.query_row("SELECT EXISTS(SELECT 1 FROM users WHERE id=?1)",params![user_id],|r|r.get(0)).map_err(|e|e.to_string())?; if !exists{return Err("usuário não encontrado".into())} conn.execute("DELETE FROM user_preferences WHERE key='active_user'",[]).map_err(|e|e.to_string())?; conn.execute("INSERT INTO user_preferences(user_id,key,value) VALUES(?1,'active_user',?1)",params![user_id]).map_err(|e|e.to_string())?; Ok(()) }
 pub fn toggle_favorite(&self,user_id:i64,game_id:i64)->CatalogResult<()> { let conn=self.connection()?; let exists:bool=conn.query_row("SELECT EXISTS(SELECT 1 FROM favorites WHERE user_id=?1 AND game_id=?2)",params![user_id,game_id],|r|r.get(0)).map_err(|e|e.to_string())?; if exists {conn.execute("DELETE FROM favorites WHERE user_id=?1 AND game_id=?2",params![user_id,game_id])} else {conn.execute("INSERT INTO favorites(user_id,game_id) VALUES(?1,?2)",params![user_id,game_id])}.map_err(|e|e.to_string())?; Ok(()) }
 pub fn is_favorite(&self,user_id:i64,game_id:i64)->CatalogResult<bool>{let conn=self.connection()?;conn.query_row("SELECT EXISTS(SELECT 1 FROM favorites WHERE user_id=?1 AND game_id=?2)",params![user_id,game_id],|r|r.get(0)).map_err(|e|e.to_string())}
 pub fn start_play_session(&self,user_id:i64,game_id:i64)->CatalogResult<i64>{let conn=self.connection()?;conn.execute("INSERT INTO play_history(user_id,game_id,started_at) VALUES(?1,?2,strftime('%s','now'))",params![user_id,game_id]).map_err(|e|e.to_string())?;Ok(conn.last_insert_rowid())}
 pub fn finish_play_session(&self,session_id:i64,seconds:i64)->CatalogResult<()> {let conn=self.connection()?;conn.execute("UPDATE play_history SET ended_at=started_at+?2 WHERE id=?1",params![session_id,seconds]).map_err(|e|e.to_string())?;Ok(())}
 pub fn user_play_seconds(&self,user_id:i64)->CatalogResult<i64>{let conn=self.connection()?;conn.query_row("SELECT COALESCE(SUM(ended_at-started_at),0) FROM play_history WHERE user_id=?1",params![user_id],|r|r.get(0)).map_err(|e|e.to_string())}
 pub fn list_games(&self)->CatalogResult<Vec<CatalogGame>> { self.list_games_for_user(self.active_user()?.id) }
 pub fn list_games_for_user(&self,user_id:i64)->CatalogResult<Vec<CatalogGame>>{ let conn=self.connection()?; let mut stmt=conn.prepare("SELECT id,identity_key,title,platform FROM games ORDER BY title").map_err(|e|e.to_string())?; let rows=stmt.query_map([],|r|Ok((r.get::<_,i64>(0)?,r.get::<_,String>(1)?,r.get::<_,String>(2)?,r.get::<_,String>(3)?))).map_err(|e|e.to_string())?; let mut games=Vec::new(); for row in rows { let (id,key,title,platform)=row.map_err(|e|e.to_string())?; let favorite:bool=conn.query_row("SELECT EXISTS(SELECT 1 FROM favorites WHERE user_id=?1 AND game_id=?2)",params![user_id,id],|r|r.get(0)).map_err(|e|e.to_string())?; let mut installs=conn.prepare("SELECT id,source,platform,install_path,install_kind,available,requires_disc FROM installations WHERE game_id=?1").map_err(|e|e.to_string())?; let installations=installs.query_map(params![id],|r|Ok(Installation{id:r.get(0)?,source:r.get(1)?,platform:r.get(2)?,install_path:r.get(3)?,install_kind:r.get(4)?,available:r.get::<_,i32>(5)?!=0,requires_disc:r.get::<_,i32>(6)?!=0})).map_err(|e|e.to_string())?.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?; games.push(CatalogGame{id,identity_key:key,title,platform,favorite,installations}); } Ok(games) }
}
